def _split_supported_head_dim(total_d: int, *, op_name: str) -> tuple[int, int]:
    d = 1 << (total_d.bit_length() - 1)
    d_remain = total_d - d
    if d_remain != 0 and d_remain & (d_remain - 1):
        raise ValueError(
            f"{op_name} only supports head dims that split into two power-of-two chunks, got {total_d}"
        )
    return d, d_remain


